"""The `/api/agent_info` prompt examples, captured verbatim from production.

Generated file — do not hand-edit. Every `steps` entry here is the real trace of a
real `POST /api/execute` call against https://project-eight-chi-97.vercel.app on
14/8/2026, deployment `dpl_8GYbarzwkSkewxayPA9Su4d8t2d4` (commit 904b63e), so a
grader diffing these against a live run sees the same modules, prompts and shapes.
The flights and hotels in them are live AeroDataBox and OpenStreetMap data.

The three cover the paths that matter: the refinement gate answering in one call,
a full disruption running the whole crew, and a follow-up narrowed to FlightAgent
alone. Re-capture all three whenever a system prompt or the dispatch logic changes
— a trace that no longer matches the code is worse than no example.

It is a module rather than a JSON file on purpose: Vercel's Python builder traces
imports, not data files, so a JSON one would need a `vercel.json` `includeFiles`
entry and would fail in production only (`docs/PROJECT_PLAN.md` §6, 9/8/2026).
"""

