                                       'of Transport and Road Safety prescribes otherwise by order '
                                       'under section 9A(a)(2) of the Principal Law as enacted by '
                                       'this Amendment:  \n'
                                       '1. The flight operator or organizer shall offer the '
                                       "passenger, at the passenger's choice, a replacement flight "
                                       'ticket departing from a different point of origin or '
                                       'arriving at a different destination from those in the '
                                       'original ticket, under conditions as similar as possible '
                                       'to the conditions of the original ticket and at the '
                                       'earliest possible time, or at a later time coordinated '
                                       'with the passenger, subject to seat availability, all in '
                                       'order to assist the passenger in reaching the original '
                                       'destination stated on the original ticket;\n'
                                       '2. A flight operator or organizer offering a replacement '
                                       'ticket under paragraph (1) shall inform the passenger '
                                       'clearly of the right to choose between reimbursement and '
                                       "that replacement ticket. The passenger's consent to "
                                       'receive such a replacement ticket shall be given in '
                                       'writing.\n'
                                       '\n'
                                       '[S16] 2024 Interpretative Guidelines on Regulations (EC) '
                                       'No 261/2004 and No 2027/97\n'
                                       'Namespace: rights-eu\n'
                                       'Retrieval score: 0.514223\n'
                                       'Selection reason: semantic\n'
                                       'Document type: passenger_rights\n'
                                       'Section: 2024 Interpretative Guidelines on Regulations '
                                       '(EC) No 261/2004 and No 2027/97 > 3. EVENTS GIVING RIGHTS '
                                       'UNDER REGULATION (EC) No 261/2004 > 3.2.1. Definition of '
                                       'cancellation\n'
                                       'Provision ID: \n'
                                       'Legal citation: Commission Notice C/2024/5687; CELEX '
                                       '52024XC05687\n'
                                       'Official source: '
                                       'https://eur-lex.europa.eu/legal-content/EN/TXT/PDF/?uri=CELEX:52024XC05687\n'
                                       'Excerpt:\n'
                                       '### 3.2.1. Definition of cancellation  \n'
                                       'Article 2, point (l), of Regulation (EC) No 261/2004 '
                                       'defines ‘cancellation’ as the non-operation of a flight '
                                       'that was previously planned and on which at least one '
                                       'place was reserved.  \n'
                                       'Cancellation occurs in principle where the planning of the '
                                       'original flight is abandoned and passengers of this flight '
                                       'join passengers on a flight that was also planned, but '
                                       'independently of the original flight. Article 2, point '
                                       '(l), does not require an express decision of cancellation '
                                       'by the air '
                                       'carrier[(55)](https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:52024XC05687#ntr55-C_202405687EN.000101-E0055).  \n'
                                       'A flight that was carried out between the places of '
                                       'departure and arrival in accordance with the planned '
                                       'schedule but during which an unscheduled stopover took '
                                       'place cannot be regarded as '
                                       'cancelled[(56)](https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:52024XC05687#ntr56-C_202405687EN.000101-E0056).  \n'
                                       'By contrast, the '
                                       'Court[(57)](https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:52024XC05687#ntr57-C_202405687EN.000101-E0057) '
                                       'considers that it cannot, as a rule, be concluded that '
                                       'there is a flight delay or cancellation on the basis of a '
                                       '‘delay’ or a ‘cancellation’ being shown on the airport '
                                       'departures board or announced by the air carrier’s staff. '
                                       'Similarly, the fact that passengers recover their luggage '
                                       'or obtain new boarding cards is not, as a rule, a deciding '
                                       'factor to ascertain that a flight has been cancelled. '
                                       'These circumstances are not connected with the objective '
                                       'characteristics of the flight as such and may arise from '
                                       'different factors. In particular, the Court highlighted '
                                       'that these circumstances (i.e. the announcement of a '
                                       'flight as being ‘delayed’ or ‘cancelled’) can ‘be '
                                       'attributable to inaccurate classifications or to factors '
                                       'obtaining in the airport concerned or, yet again, they may '
                                       'be unavoidable given the waiting time and the fact that it '
                                       'is necessary for the passengers concerned to spend the '
                                       'night in a hotel’.\n'
                                       '\n'
                                       '[S17] General Conditions of Carriage for Passengers and '
                                       'Baggage\n'
                                       'Namespace: coc-lh\n'
                                       'Retrieval score: 0.507855\n'
                                       'Selection reason: semantic\n'
                                       'Document type: conditions_of_carriage\n'
                                       'Section: General conditions of carriage for passengers and '
                                       'baggage > Article 5: Reservations\n'
                                       'Provision ID: \n'
                                       'Legal citation: \n'
                                       'Official source: '
                                       'https://www.lufthansa.com/cn/en/terms-and-conditions-lh\n'
                                       'Excerpt:\n'
                                       '## Article 5: Reservations  \n'
                                       '**Conditions for reservations**  \n'
                                       '5.1.  \n'
                                       '5.1.1. Each flight coupon will be accepted only for '
                                       'carriage in the Travel Class specified on the coupon and '
                                       'for the day and flight for which there is a seat '
                                       'reservation. For tickets without a seat reservation, a '
                                       'seat may be reserved later if there is still one available '
                                       'on the desired flight.  \n'
                                       '5.1.2. We or one of our Authorized Agents will record your '
                                       'booking(s). We will send you a written passenger receipt '
                                       'on request.  \n'
                                       '5.1.3. Certain fares are subject to conditions that limit '
                                       'your right to rebook or cancel reservations.  \n'
                                       '(5.2. has been deleted.)  \n'
                                       '**Personal data**  \n'
                                       '5.3. We process your personal data according to all the '
                                       'relevant data privacy regulations and only for the '
                                       'following purposes: making flight bookings, purchasing '
                                       'tickets, obtaining additional services,refund and '
                                       'rebooking of tickets and additional services, development '
                                       'and provision of services, facilitating immigration and '
                                       'entry procedures, as well as making information associated '
                                       'with the organization of your journey available to the '
                                       'relevant government agencies and other airlines, or to '
                                       'other providers of the aforementioned services.  \n'
                                       '**Advance seat reservations**  \n'
                                       '5.4.  \n'
                                       '5.4.1. You have the option of making an advance seat '
                                       'reservation on some Lufthansa flights. In the context of '
                                       'this service, you can choose –if available – a specific '
                                       'seating category (aisle, window or middle seat, a seat '
                                       'with more legroom). Some fares are subject to a charge for '
                                       'this service, depending on the type of seat. The price may '
                                       'vary based on the seat category, time and type of booking, '
                                       'flight and route. There is no obligation to make a '
                                       '(chargeable) advance seat reservation.You can find more '
                                       'information on the page about [__ Seat '
                                       'reservations](https://www.lufthansa.com/cn/en/advance-seat-reservation).  \n'
                                       '5.4.2.If you decide not to pay for a seat reservation, you '
                                       'will be allocated a seat free of charge at check-in. '
                                       'Changes to an already selected or allocated seat may incur '
                                       'a charge depending on the selected fare. Whenever you use '
                                       'the “automated check-in” service, at the end of the '
                                       'process you are given the option of selecting a seat other '
                                       'than the one assigned to you. This may incur a fee '
                                       'depending on the fare, providing other seats are still '
                                       'available. However, we cannot guarantee specific seats or '
                                       'the availability of a specific seat category.  \n'
                                       '5.4.3 If you rebook your flight, your existing seat '
                                       'reservation expires and you can proceed with a new seat '
                                       'reservation which may incur higher costs depending on the '
                                       'fare, seat category, time of rebooking and flight route.\n'
                                       '\n'
