                                       'Document type: passenger_rights\n'
                                       'Section: 2024 Interpretative Guidelines on Regulations '
                                       '(EC) No 261/2004 and No 2027/97 > 4. PASSENGERS’ RIGHTS > '
                                       '4.4.13. Re-routing and arrival more than 2 hours after the '
                                       'scheduled arrival time but less than 3 hours\n'
                                       'Provision ID: \n'
                                       'Legal citation: Commission Notice C/2024/5687; CELEX '
                                       '52024XC05687\n'
                                       'Official source: '
                                       'https://eur-lex.europa.eu/legal-content/EN/TXT/PDF/?uri=CELEX:52024XC05687\n'
                                       'Excerpt:\n'
                                       '### 4.4.13. Re-routing and arrival more than 2 hours after '
                                       'the scheduled arrival time but less than 3 hours  \n'
                                       'The Court has confirmed that passengers who are informed '
                                       'of the cancellation of their flight less than 7 days '
                                       'before the scheduled time of departure are entitled to the '
                                       'compensation referred to in Article 5(1), point (c), if '
                                       'the re-routing offered by the air carrier enabled them to '
                                       'reach the final destination more than 2 hours but less '
                                       'than 3 hours after the scheduled time of arrival of the '
                                       'cancelled '
                                       'flight[(113)](https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:52024XC05687#ntr113-C_202405687EN.000101-E0113).  \n'
                                       'However, if passengers re-route themselves, because they '
                                       'have been informed or have sufficient evidence that their '
                                       'flight will arrive at its destination with a long delay, '
                                       'they are not eligible for compensation if they reach their '
                                       'final destination (with the new flight) with a delay of '
                                       'less than 3 hours after the scheduled arrival time of '
                                       'their originally booked '
                                       'flight[(114)](https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:52024XC05687#ntr114-C_202405687EN.000101-E0114).  \n'
                                       'F.Reimbursement in the event of downgrading\n'
                                       '\n'
                                       '[S20] 2024 Interpretative Guidelines on Regulations (EC) '
                                       'No 261/2004 and No 2027/97\n'
