                                       'Section: 2024 Interpretative Guidelines on Regulations '
                                       '(EC) No 261/2004 and No 2027/97 > 3. EVENTS GIVING RIGHTS '
                                       'UNDER REGULATION (EC) No 261/2004 > 3.2.2. Change of '
                                       'departure time\n'
                                       'Provision ID: \n'
                                       'Legal citation: Commission Notice C/2024/5687; CELEX '
                                       '52024XC05687\n'
                                       'Official source: '
                                       'https://eur-lex.europa.eu/legal-content/EN/TXT/PDF/?uri=CELEX:52024XC05687\n'
                                       'Excerpt:\n'
                                       '### 3.2.2. Change of departure time  \n'
                                       'Without prejudice to Section 3.3.1 and in order to avoid a '
                                       'situation where air carriers present a flight as '
                                       'continuously ‘delayed’ instead of ‘cancelled’, it was '
                                       'considered useful to highlight the distinction between a '
                                       '‘cancellation’ and a ‘delay’. A flight may generally tend '
                                       'to be considered as cancelled when its flight number '
                                       'changes, but in practice, this might not always be a '
                                       'determining criterion. Indeed, a flight may experience '
                                       'such a long delay that it departs the day after it was '
                                       'scheduled and therefore is given an annotated flight '
                                       'number (e.g. XX 1234a instead of XX 1234) to distinguish '
                                       'it from the flight on this subsequent day that has the '
                                       'same number. However, in this case, it could still be '
                                       'considered as a delayed flight and not a cancelled flight. '
                                       'This should be assessed on a case-by-case basis.  \n'
                                       'By way of example, a flight is not regarded as having been '
                                       '‘cancelled’ if the operating air carrier postpones the '
                                       'time of departure of the flight by less than 3 hours, '
                                       'without making any other changes to this '
                                       'flight[(58)](https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:52024XC05687#ntr58-C_202405687EN.000101-E0058).  \n'
                                       'However, a flight must be regarded as having been '
                                       '‘cancelled’ if the operating air carrier brings the '
                                       'departure time of the flight forward by more than 1 '
                                       'hour[(59)](https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:52024XC05687#ntr59-C_202405687EN.000101-E0059).\n'
                                       '\n'
