                                       'and which require or make reasonable a deviation from the '
                                       'sequence of the ticket. The fastest way to reach us is via '
                                       'the [__ '
                                       'form](https://www.lufthansa.com/de/en/modified-coupon-sequence)provided '
                                       'for this purpose. If you are unable to provide proof prior '
                                       'to the start of the carriage, you will be required to pay '
                                       'any difference to the higher fare determined in accordance '
                                       'with Article 3.3.3 prior to departure. If we do not '
                                       'receive payment, we will charge you the difference after '
                                       'carriage. For this purpose, you must provide us with your '
                                       'address before departure and verify its accuracy (e.g. by '
                                       'presenting an official ID) so that we can claim the '
                                       'difference afterwards. Please note that we may make '
                                       'carriage dependent on a) receipt of payment in the amount '
                                       'of the difference prior to departure or b) whether you '
                                       'have provided us with your address prior to departure and '
                                       'verified its accuracy. The difference will not be '
                                       'calculated retrospectively if you provide proof of the '
                                       'reasons for the changes in the sequence of the ticket '
