                                                       'compensation, but the exact result depends '
                                                       'on the applicable regime and the airline’s '
                                                       'proof of any exception. Under Israeli law, '
                                                       'monetary compensation is set by the First '
                                                       'Schedule and is subject to annual '
                                                       'updating, so the current amount cannot be '
                                                       'confirmed from the supplied excerpt alone; '
                                                       'the law also allows the carrier to avoid '
                                                       'monetary compensation if it proves '
                                                       'extraordinary circumstances beyond its '
