                                                       'control, a protected strike or '
                                                       'work-to-rule, or cancellation to avoid '
                                                       'desecration of the Sabbath or a Jewish '
                                                       'holiday. Under EU261, compensation is EUR '
                                                       '250 / EUR 400 / EUR 600 depending on '
                                                       'distance band, and it may be reduced by '
                                                       '50% if qualifying rerouting arrives within '
                                                       'the article’s delay thresholds.',
